arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_0ab4ee138af441d491a3f29f7a788ed9.Models
@using sv_0ab4ee138af441d491a3f29f7a788ed9.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (!_submitted)
{
    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="card mt-4">
        <div class="card-body">
            @if (!string.IsNullOrEmpty(_errorMessage))
            {
                <div class="alert alert-danger">@_errorMessage</div>
            }

            @switch (_currentStep)
            {
                case 1:
                    <StepPersonalInfo FullName="@_fullName"
                                      Email="@_email"
                                      Phone="@_phone"
                                      Address="@_address"
                                      FullNameChanged="v => _fullName = v"
                                      EmailChanged="v => _email = v"
                                      PhoneChanged="v => _phone = v"
                                      AddressChanged="v => _address = v" />
                    break;
                case 2:
                    <StepWorkHistory Entries="_workEntries"
                                     CurrentFlags="_currentJobFlags" />
                    break;
                case 3:
                    <StepReferences References="_references" />
                    break;
                case 4:
                    <StepCoverLetter CoverLetter="@_coverLetter"
                                     CoverLetterChanged="v => _coverLetter = v"
                                     MaxLength="2000" />
                    break;
                case 5:
                    <StepReview FullName="@_fullName"
                                Email="@_email"
                                Phone="@_phone"
                                Address="@_address"
                                WorkEntries="_workEntries"
                                CurrentFlags="_currentJobFlags"
                                References="_references"
                                CoverLetter="@_coverLetter"
                                OnEditSection="GoToStep" />
                    break;
            }

            <div class="d-flex justify-content-between mt-4">
                @if (_currentStep > 1)
                {
                    <button class="btn btn-outline-secondary" @onclick="GoBack" disabled="@_isProcessing">
                        Back
                    </button>
                }
                else
                {
                    <span></span>
                }

                @if (_currentStep < 5)
                {
                    <button class="btn btn-primary" @onclick="GoNext" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="Submit" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Submit Application
                    </button>
                }
            </div>
        </div>
    </div>
}
else
{
    <div class="card mt-4">
        <div class="card-body text-center">
            <h2 class="text-success mb-3">✅ Application Submitted!</h2>
            <p class="lead">Your application has been received.</p>
            <p><strong>Application ID:</strong> @_applicationId</p>
            <a href="/apply" class="btn btn-primary mt-3">Submit Another Application</a>
        </div>
    </div>
}

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();
    private bool _isProcessing;
    private bool _submitted;
    private int? _applicationId;
    private string? _errorMessage;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<bool> _currentJobFlags = new() { false };

    // Step 3
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _errorMessage = null;
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        _errorMessage = null;
        _currentStep--;
    }

    private async Task GoNext()
    {
        _errorMessage = null;
        _isProcessing = true;

        try
        {
            if (!await ValidateCurrentStep())
                return;

            _completedSteps.Add(_currentStep);
            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName))
                    { _errorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                    { _errorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                    { _errorMessage = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                    { _errorMessage = "Address is required."; return false; }

                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                    { _errorMessage = "Please enter a valid email address."; return false; }
                break;

            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                        { _errorMessage = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                        { _errorMessage = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                        { _errorMessage = "Start date is required for all entries."; return false; }
                }
                break;

            case 3:
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                        { _errorMessage = "Reference name is required."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                        { _errorMessage = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                        { _errorMessage = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                        { _errorMessage = "Phone is required for all references."; return false; }
                }
                break;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                    { _errorMessage = "Cover letter is required."; return false; }
                break;
        }

        return true;
    }

    private async Task Submit()
    {
        _errorMessage = null;
        _isProcessing = true;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);

            var workEntries = _workEntries.Select((e, i) => new WorkEntry(
                e.Company, e.Title, e.StartDate,
                _currentJobFlags[i] ? null : e.EndDate,
                e.Description ?? ""
            )).ToList();

            var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, new WorkHistory(workEntries), refs, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string? Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@{
    var stepNames = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav aria-label="Application steps">
    <ol class="step-indicator d-flex list-unstyled mb-0 p-3 bg-light rounded">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var step = i + 1;
            var isActive = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = step > CurrentStep && !isCompleted;
            var cssClass = isActive ? "active" : isCompleted ? "completed" : "dimmed";

            <li class="step-item flex-fill text-center @cssClass"
                @onclick="() => OnStepClick(step)"
                style="@(isCompleted ? "cursor:pointer" : "cursor:default")">
                <div class="step-circle mx-auto mb-1 @cssClass">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="d-none d-md-block">@stepNames[i]</small>
            </li>

            @if (i < stepNames.Length - 1)
            {
                <li class="step-connector flex-fill align-self-center">
                    <hr class="@(CompletedSteps.Contains(step) ? "text-success" : "text-muted")" />
                </li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
}

.step-circle.active {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step-circle.completed {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-circle.dimmed {
    opacity: 0.5;
}

.step-item.dimmed small {
    opacity: 0.5;
}

.step-item.active small {
    font-weight: 600;
    color: #0d6efd;
}

.step-item.completed small {
    color: #198754;
}

.step-connector hr {
    margin: 0;
    border-top-width: 2px;
}

@using static sv_0ab4ee138af441d491a3f29f7a788ed9.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5 class="card-title mb-0">Position @(index + 1)</h5>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">
                        Remove
                    </button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="Entries[index].Company" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="Entries[index].Title" />
                </div>
            </div>

            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="Entries[index].StartDate" />
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="Entries[index].EndDate"
                           disabled="@CurrentFlags[index]" />
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               checked="@CurrentFlags[index]"
                               @onchange="e => OnCurrentChanged(index, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @bind="Entries[index].Description"></textarea>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary" @onclick="AddEntry">
    + Add Another Position
</button>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public List<bool> CurrentFlags { get; set; } = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        CurrentFlags.Add(false);
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            CurrentFlags.RemoveAt(index);
        }
    }

    private void OnCurrentChanged(int index, bool isCurrent)
    {
        CurrentFlags[index] = isCurrent;
        if (isCurrent)
        {
            Entries[index].EndDate = null;
        }
    }
}

@using static sv_0ab4ee138af441d491a3f29f7a788ed9.Components.Pages.Apply

<h4 class="mb-3">References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h5 class="card-title mb-0">Reference @(index + 1)</h5>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">
                        Remove
                    </button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="References[index].Name" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="References[index].Relationship" />
                </div>
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="References[index].Email" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="References[index].Phone" />
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary" @onclick="AddReference">
        + Add Reference
    </button>
}

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }
}

@using static sv_0ab4ee138af441d491a3f29f7a788ed9.Components.Pages.Apply

<h4 class="mb-3">Review Your Application</h4>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <button class="btn btn-link btn-sm p-0" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</button>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Name</dt>
            <dd class="col-sm-9">@FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@Address</dd>
        </dl>
