.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
}

.step-circle.active {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step-circle.completed {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-circle.dimmed {
    opacity: 0.5;
}

.step-item.dimmed small {
    opacity: 0.5;
}

.step-item.active small {
    font-weight: 600;
    color: #0d6efd;
}

.step-item.completed small {
    color: #198754;
}

.step-connector hr {
    margin: 0;
    border-top-width: 2px;
